{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Aromatherapy & Personalized Blends</title>
  <meta name="description" content="A safety-first aromatherapy practice offering bespoke blends, education, and VIP days. Sensitive to pregnancy, pets, and dilution best practices.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme">
  <header class="site-header">
    <div class="inner">
      <a class="brand" href="index.html">
        <svg class="logo" width="44" height="44" viewBox="0 0 64 64" aria-hidden="true">
          <circle cx="32" cy="32" r="30" fill="url(#g)" stroke="#fff" stroke-width="2" />
          <defs>
            <linearGradient id="g" x1="0" x2="1">
              <stop offset="0" stop-color="#A3D9C8" />
              <stop offset="1" stop-color="#8CC7E7" />
            </linearGradient>
          </defs>
          <path d="M20 44c6-8 12-10 24-14" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round"/>
        </svg>
        <span class="name">{{BUSINESS_NAME}}</span>
      </a>
      <nav class="main-nav">
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Blends</a>
        <a href="shop.html">Shop</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">About</a>
        <a href="book.html" class="book">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
      <button class="menu-toggle" aria-label="Toggle menu" id="menuToggle">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="pattern" aria-hidden="true"></div>
      <div class="hero-inner inner">
        <div class="hero-copy">
          <h1 class="eyebrow">Aromatherapy with clarity & care</h1>
          <h2>{{TAGLINE}}</h2>
          <p class="lead">Personalized essential oil blends, safety-forward guidance, and immersive VIP Days for busy people who want mindful scent solutions — without medical promises.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="book.html">Schedule a consult</a>
          </div>
        </div>
        <aside class="hero-aside">
          <div class="card">
            <h3>VIP Day</h3>
            <p>Intensive 1:1 day to craft routines, blends, and an at-home plan tailored for your environment & routines.</p>
            <a class="btn small" href="pricing.html">See VIP options</a>
          </div>
          <div class="contact-small">
            <strong>{{PRACTITIONER_NAME}}</strong>
            <a href="tel:{{PHONE}}">{{PHONE}}</a>
            <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
          </div>
        </aside>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof inner">
      <h3>Kind words & trusted partners</h3>
      <div class="proof-grid">
        <blockquote class="testimonial">
          "A thoughtful practitioner who made blends feel accessible and safe."
          <cite>— Client in {{CITY}}, {{STATE}}</cite>
        </blockquote>
        <div class="logos" aria-hidden="true">
          <span class="logo-pill">WellnessCo</span>
          <span class="logo-pill">StudioX</span>
          <span class="logo-pill">Market</span>
        </div>
      </div>
    </section>

    <!-- BENEFITS -->
    <section class="benefits inner">
      <h3>What you'll get</h3>
      <ul class="benefit-list">
        <li>
          <strong>Personalized blends</strong>
          <p>Top, middle and base notes chosen for your life, scent preferences, and safety considerations.</p>
        </li>
        <li>
          <strong>Clear safety guidance</strong>
          <p>Practical dilution, patch testing, and pet/pregnancy considerations explained plainly.</p>
        </li>
        <li>
          <strong>Easy rituals</strong>
          <p>Simple, repeatable routines and product recommendations you can use today.</p>
        </li>
      </ul>
    </section>

    <!-- PROCESS -->
    <section class="process inner" id="process">
      <h3>How a session flows</h3>
      <ol class="steps">
        <li>
          <span class="step-num">1</span>
          <div>
            <h4>Welcome & intake</h4>
            <p>We review goals, sensitivities, and environment — notes are used to guide safe blend selection.</p>
          </div>
        </li>
        <li>
          <span class="step-num">2</span>
          <div>
            <h4>Scent exploration</h4>
            <p>Sample oils and discuss aroma profiles; no medical claims are made — we focus on scent, comfort, and safety.</p>
          </div>
        </li>
        <li>
          <span class="step-num">3</span>
          <div>
            <h4>Custom blending</h4>
            <p>Create a blend with clear dilution and usage notes; receive written guidance for home use.</p>
          </div>
        </li>
        <li>
          <span class="step-num">4</span>
          <div>
            <h4>Follow-up</h4>
            <p>Short check-in to ensure blends are comfortable and adjusting recommendations if needed.</p>
          </div>
        </li>
      </ol>
    </section>

    <!-- FAQ -->
    <section class="faq inner" id="faq">
      <h3>Common questions — safety first</h3>
      <div class="accordion">
        <div class="item">
          <button class="q">What dilution should I use?</button>
          <div class="a">Dilution depends on age, sensitivity, and intended use. Typical adult topical dilutions are 1–3% for roll-ons and 0.5–2% for facial products. Exact percentages will be provided with each blend. Avoid self-treating serious conditions; this is not medical advice.</div>
        </div>
        <div class="item">
          <button class="q">How do I patch test?</button>
          <div class="a">Apply a small diluted amount to the inner forearm and wait 24 hours. If irritation, redness, or discomfort appears, discontinue use and contact the practitioner.</div>
        </div>
        <div class="item">
          <button class="q">Are essential oils safe for pets?</button>
          <div class="a">Many oils can be irritating or harmful to animals. I provide pet-safe recommendations and diffuser guidelines; never apply human blends directly to pets and avoid diffusing continuously in enclosed spaces.</div>
        </div>
        <div class="item">
          <button class="q">What about pregnancy?</button>
          <div class="a">Pregnancy requires extra caution. Some oils and higher dilutions are not appropriate. If pregnant or nursing, we use only oils and dilutions considered acceptable by current aromatherapy safety resources and will refer to medical providers when needed.</div>
        </div>
      </div>
    </section>

    <!-- LEAD MAGNET -->
    <section class="lead-magnet inner" id="lead">
      <div class="magnet-grid">
        <div>
          <h3>Free Guide: Home Diffusing Basics</h3>
          <p>Download a clear, safety-focused guide on diffusing, room guidelines, and a starter checklist.</p>
        </div>
        <form id="leadForm" class="magnet-form" novalidate>
          <label for="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Your name">
          <label for="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@example.com" required>
          <label for="interest">I'm interested in</label>
          <select id="interest" name="interest">
            <option>Personal blends</option>
            <option>VIP Day</option>
            <option>Workshops</option>
          </select>
          <button class="btn primary" type="submit">Get the guide</button>
          <p class="fine-print">We respect your privacy. Materials include safety-first recommendations and no medical claims.</p>
        </form>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta inner">
      <div>
        <h3>Ready to craft your scent plan?</h3>
        <p>Book a discovery call or start with a single session. Personalized notes, dilution guidance, and an at-home plan included.</p>
        <div class="cta-actions">
          <a class="btn primary" href="book.html">Book a discovery call</a>
          <a class="btn ghost" href="services.html">View offerings</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="inner footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>Based in {{CITY}}, {{STATE}} — safety-first aromatherapy consultations.</p>
      </div>
      <nav>
        <a href="about.html">About</a>
        <a href="blends.html">Blends</a>
        <a href="contact.html">Contact</a>
      </nav>
      <div>
        <a href="tel:{{PHONE}}">{{PHONE}}</a>
        <a href="mailto:{{EMAIL}}">Email</a>
      </div>
    </div>
    <div class="legal">&copy; <span id="year"></span> {{BUSINESS_NAME}}. All rights reserved. Not a substitute for medical care.</div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
